function setConnective(type) {
    document.getElementById('btn-conn-or').classList.toggle('active', type === 'or');
    document.getElementById('btn-conn-and').classList.toggle('active', type === 'and');

    const setEl = document.getElementById('conn-solution-set');
    const desc = document.getElementById('conn-desc');

    if (type === 'or') {
        setEl.innerText = '{-2, 20}';
        desc.innerText = 'Under OR: Any value that makes EITHER equation true is a solution (Union: {-2} ∪ {20}).';
    } else {
        setEl.innerText = '∅ (Empty Set)';
        desc.innerText = 'Under AND: A value must satisfy BOTH equations simultaneously. Since no number equals both 20 and -2, the intersection is empty.';
    }
}
